    line = line.strip()
    if not line: continue
    parts = line.split(',')
    if len(parts) >= 3:
        h_id = parts[0].strip()
        h = parts[1].strip()
        p = parts[2].strip()
        h_val = float(h) if h and h != 'None' else None
        p_val = int(p) if p and p != 'None' else None
        if h_id not in heroes:
            heroes[h_id] = {'id': h_id, 'height': None, 'pub_id': None}
        if h_val is not None:
            heroes[h_id]['height'] = h_val
        if p_val is not None:
            heroes[h_id]['pub_id'] = p_val
filtered = []
for hero in heroes.values():
    h = hero['height']
    p = hero['pub_id']
    if h is not None and 150 <= h <= 180 and p is not None:
        filtered.append(hero)
marvel = [h for h in filtered if h['pub_id'] == 13]
pct = (len(marvel) / len(filtered)) * 100 if filtered else 0
